export type ObjectKind =
  | 'sun'
  | 'planet'
  | 'moon'
  | 'spacecraft'
  | 'model'
  | 'place'
  | 'star'
  | 'sStar'
  | 'milkyWay'
  | 'blackHole'
  | 'galaxy'
  | 'open-cluster'
  | 'globular-cluster'
  | 'nebula'
  | 'gc-cluster'
  | 'galaxy-group'
  | 'galaxy-cluster'
  | 'supercluster'
  | 'void'
  | 'exhibit'
  | 'tour';
